   394	 * asn1_get_object_id_der:
   395	 * @der: DER data to decode containing the OBJECT IDENTIFIER
   396	 * @der_len: Length of DER data to decode.
   397	 * @ret_len: Output variable containing the length of the DER data.
   398	 * @str: Pre-allocated output buffer to put the textual object id in.
   399	 * @str_size: Length of pre-allocated output buffer.
   400	 *
   401	 * Converts a DER encoded object identifier to its textual form. This
   402	 * function expects the DER object identifier without the tag.
   403	 *
   404	 * Returns: %ASN1_SUCCESS on success, or an error.
   405	 **/
   406	int
   407	asn1_get_object_id_der (const unsigned char *der, int der_len, int *ret_len,
   408	                        char *str, int str_size)
   409	{
   410	  int len_len, len, k;
   411	  int leading;
   412	  char temp[LTOSTR_MAX_SIZE];
   413	  uint64_t val, val1;
   414	
   415	  *ret_len = 0;
   416	  if (str && str_size > 0)
   417	    str[0] = 0;                 /* no oid */
   418	
   419	  if (str == NULL || der_len <= 0)
   420	    return ASN1_GENERIC_ERROR;
   421	
   422	  len = asn1_get_length_der (der, der_len, &len_len);
   423	
   424	  if (len <= 0 || len + len_len > der_len)
   425	    return ASN1_DER_ERROR;
   426	
   427	  val1 = der[len_len] / 40;
   428	  val = der[len_len] - val1 * 40;
   429	
   430	  _asn1_str_cpy (str, str_size, _asn1_ltostr (val1, temp));
   431	  _asn1_str_cat (str, str_size, ".");
   432	  _asn1_str_cat (str, str_size, _asn1_ltostr (val, temp));
   433	
   434	  val = 0;
   435	  leading = 1;
   436	  for (k = 1; k < len; k++)
   437	    {
   438	      /* X.690 mandates that the leading byte must never be 0x80
   439	       */
   440	      if (leading != 0 && der[len_len + k] == 0x80)
   441	        return ASN1_DER_ERROR;
   442	      leading = 0;
   443	
   444	      /* check for wrap around */
   445	      if (INT_LEFT_SHIFT_OVERFLOW (val, 7))
   446	        return ASN1_DER_ERROR;
   447	
   448	      val = val << 7;
   449	      val |= der[len_len + k] & 0x7F;
   450	
   451	      if (!(der[len_len + k] & 0x80))
   452	        {
   453	          _asn1_str_cat (str, str_size, ".");
   454	          _asn1_str_cat (str, str_size, _asn1_ltostr (val, temp));
   455	          val = 0;
   456	          leading = 1;
   457	        }
   458	    }
   459	
   460	  if (INT_ADD_OVERFLOW (len, len_len))
   461	    return ASN1_DER_ERROR;
   462	
   463	  *ret_len = len + len_len;
   464	
   465	  return ASN1_SUCCESS;
   466	}
